const now = new Date();
const d7 = new Date(now.getTime() - 7*24*60*60*1000);
const d1 = new Date(now.getTime() - 24*60*60*1000);
const iso = x => x.toISOString().split('T')[0];
return [{ json: {
  nowIso: now.toISOString(),
  today: iso(now),
  yesterday: iso(d1),
  weekAgo: iso(d7),
}}];

const kpis  = $('Read Daily KPIs (7d)').all().map(i => i.json);
const ads   = $('Read Active Ads').all().map(i => i.json);
const email = $('Read Email Performance').all().map(i => i.json);
const nowIso = $('Prep Time Window').item.json.nowIso;

const anomalies = [];
const add = (engine, type, severity, desc, current, expected, action) => {
  anomalies.push({
    'Timestamp': nowIso,
    'Engine': engine,
    'Type': type,
    'Severity': severity,
    'Description': desc,
    'Current Value': current,
    'Expected Value': expected,
    'Recommended Action': action,
    'Resolved': false
  });
};

// Baseline: last 7 days excluding today
const today = $('Prep Time Window').item.json.today;
const current = kpis.find(k => k.Date === today);
const baseline = kpis.filter(k => k.Date !== today);
const avg = (arr, f) => arr.length ? arr.reduce((a,x) => a + (Number(x[f]) || 0), 0) / arr.length : 0;

if (current && baseline.length >= 3) {
  // 1. CPA Spike
  const curCpa = Number(current['Total Ad Spend']) / Math.max(1, Number(current['New Customers']));
  const baseCpa = avg(baseline, 'Total Ad Spend') / Math.max(1, avg(baseline, 'New Customers'));
  if (baseCpa > 0 && curCpa > baseCpa * 1.5) {
    add('Acquisition', 'CPA Spike', curCpa > baseCpa * 2 ? 'Critical' : 'Warning',
      `CPA gestegen naar €${curCpa.toFixed(2)} (baseline €${baseCpa.toFixed(2)}). Creative refresh of hook-variant testen.`,
      curCpa, baseCpa,
      'Check /pattern-detector om te zien welke ads de oorzaak zijn. Pauzeer losers boven €20 spend.'
    );
  }

  // 2. CR Drop
  const curCR = Number(current['Shopify Conversion Rate']) || 0;
  const baseCR = avg(baseline, 'Shopify Conversion Rate');
  if (baseCR > 0 && curCR < baseCR * 0.7) {
    add('Conversion', 'CR Drop', curCR < baseCR * 0.5 ? 'Critical' : 'Warning',
      `Shopify CR gezakt naar ${curCR.toFixed(2)}% (baseline ${baseCR.toFixed(2)}%). Onderzoek PDP/checkout friction.`,
      curCR, baseCR,
      'Check Shopify PDP voor hero product. Test checkout flow handmatig. Review recent design changes.'
    );
  }

  // 3. Inventory Low
  if (current['Inventory Status'] === 'Critical') {
    add('Revenue', 'Inventory Low', 'Critical',
      'Voorraad hero product onder 14 dagen runway. Nu bijbestellen om stockout te voorkomen.',
      null, null,
      'Plaats bestelling bij leverancier, verhoog MOQ zodat je 60+ dagen runway hebt.'
    );
  } else if (current['Inventory Status'] === 'Watch') {
    add('Revenue', 'Inventory Low', 'Warning',
      'Voorraad hero product onder 30 dagen runway. Bestelling inplannen.',
      null, null,
      'Zet bestelling voor komende 2 weken op planning.'
    );
  }

  // 4. Pipeline Stall
  const curPipe = Number(current['B2B Pipeline Value']) || 0;
  const basePipe = avg(baseline, 'B2B Pipeline Value');
  if (basePipe > 0 && curPipe < basePipe * 0.8) {
    add('Revenue', 'Pipeline Stall', 'Warning',
      `B2B pipeline waarde gezakt van €${Math.round(basePipe)} naar €${Math.round(curPipe)}. Leads verliezen stage of niet genoeg aanvoer.`,
      curPipe, basePipe,
      'Review B2B outreach cadans. Check of Engaged+ leads niet stil zijn gevallen.'
    );
  }

  // 5. Email Drop
  const curEmailShare = Number(current['Email Revenue Share']) || 0;
  if (curEmailShare < 15 && Number(current['Total Revenue']) > 500) {
    add('Conversion', 'Email Drop', 'Warning',
      `Email share slechts ${curEmailShare.toFixed(1)}% van omzet. Flows onderpresteren of niet actief.`,
      curEmailShare, 25,
      'Check welcome flow + abandoned cart in Klaviyo. Open rate check: moet >25% zijn.'
    );
  }

  // 6. Budget Overrun (ad spend 2x baseline)
  const curSpend = Number(current['Total Ad Spend']) || 0;
  const baseSpend = avg(baseline, 'Total Ad Spend');
  if (baseSpend > 0 && curSpend > baseSpend * 2) {
    add('Acquisition', 'Budget Overrun', 'Warning',
      `Ad spend €${Math.round(curSpend)} — 2x gemiddelde (€${Math.round(baseSpend)}). Check of dit gepland was.`,
      curSpend, baseSpend,
      'Verify Meta budget caps. Check of winner scale rule niet is doorgeschoten.'
    );
  }
}

// 7. Email open rate
for (const e of email) {
  const openRate = Number(e['Open Rate']) || 0;
  if (openRate > 0 && openRate < 15) {
    add('Conversion', 'Email Drop', 'Warning',
      `Flow "${e['Flow Name']||'onbekend'}" open rate ${openRate.toFixed(1)}% — onder benchmark 15%.`,
      openRate, 25,
      'Test nieuwe subject lines. Check deliverability + domain warmup.'
    );
    break; // one alert is enough per run
  }
}

// 8. Ad fatigue check — CTR drop per ad
for (const a of ads) {
  const ctr = Number(a.CTR) || 0;
  const spend = Number(a.Spend) || 0;
  if (spend > 50 && ctr > 0 && ctr < 0.5) {
    add('Acquisition', 'Ad Fatigue', 'Warning',
      `Ad "${a['Ad Name']}" CTR ${ctr.toFixed(2)}% met €${spend} spend. Creative is op.`,
      ctr, 1.0,
      'Pause deze ad, test nieuwe hook uit hookbank (Voorraadrust of Comfort angle).'
    );
    break; // max 1 fatigue alert per run om spam te voorkomen
  }
}

return anomalies.length
  ? anomalies.map(a => ({ json: a }))
  : [{ json: { _noAnomalies: true } }];

const a = $json;
const icon = a.Severity === 'Critical' ? '🚨' : a.Severity === 'Warning' ? '⚠️' : 'ℹ️';
const txt = `${icon} *Bamboo Anomaly — ${a.Severity}*\n\n` +
  `*Type:* ${a.Type} (${a.Engine})\n` +
  `${a.Description}\n\n` +
  `*Actie:* ${a['Recommended Action']}`;
return [{ json: { text: txt } }];
